+package main
+
+import (
+	"os"
+	"strings"
+	"testing"
+)
+
+func TestAPIKeysSchemaStoresOnlyDigestsBehindTheTenantBoundary(t *testing.T) {
+	body, err := os.ReadFile("migrations/0018_api_keys.up.sql")
+	if err != nil {
+		t.Fatal(err)
+	}
+	schema := string(body)
+	for _, want := range []string{"PRIMARY KEY (installation_id, id)", "secret_sha256 bytea NOT NULL CHECK (length(secret_sha256) = 32)", "FORCE ROW LEVEL SECURITY", "current_setting('px1.installation_id', true)", "REFERENCES api_keys(installation_id, id)"} {
+		if !strings.Contains(schema, want) {
+			t.Fatalf("migration missing %q", want)
+		}
+	}
+	if strings.Contains(schema, "secret text") || strings.Contains(schema, "token text") {
+		t.Fatal("API key schema must not store plaintext secrets")
+	}
+}

diff --git a/internal/hosted/apikeys/http.go b/internal/hosted/apikeys/http.go
new file mode 100644
index 0000000..65c1422
--- /dev/null
+++ b/internal/hosted/apikeys/http.go
@@ -0,0 +1,111 @@
+package apikeys
+
+import (
+	"context"
+	"errors"
+	"math"
+	"net/http"
+	"strconv"
+	"strings"
+	"sync"
+	"time"
+)
+
+// RateLimiter is a per-key token bucket. It is process-local: with N API
+// processes a key can make up to N × the configured rate.
+type RateLimiter struct {
+	PerMinute int
+	Burst     int
+	Now       func() time.Time
+
+	mu      sync.Mutex
+	buckets map[string]*bucket
+}
+
+type bucket struct {
+	tokens float64
+	last   time.Time
+}
+
+const maxTrackedKeys = 100_000
+
+// Allow spends one token for key and, when refused, says how long to wait.
+func (l *RateLimiter) Allow(key string) (bool, time.Duration) {
+	now := time.Now()
+	if l.Now != nil {
+		now = l.Now()
+	}
+	perMinute, burst := max(l.PerMinute, 1), max(l.Burst, 1)
+	rate := float64(perMinute) / 60
+	l.mu.Lock()
+	defer l.mu.Unlock()
+	if l.buckets == nil {
+		l.buckets = map[string]*bucket{}
+	}
+	b := l.buckets[key]
+	if b == nil {
+		if len(l.buckets) >= maxTrackedKeys {
+			l.evictFull(now, rate, float64(burst))
+		}
+		b = &bucket{tokens: float64(burst), last: now}
+		l.buckets[key] = b
+	}
+	b.tokens = math.Min(float64(burst), b.tokens+now.Sub(b.last).Seconds()*rate)
+	b.last = now
+	if b.tokens >= 1 {
+		b.tokens--
+		return true, 0
+	}
+	return false, time.Duration(math.Ceil((1-b.tokens)/rate*1000)) * time.Millisecond
+}
+
+// evictFull drops buckets that have refilled completely; forgetting them
+// changes nothing because a new bucket also starts full.
+func (l *RateLimiter) evictFull(now time.Time, rate, burst float64) {
+	for key, b := range l.buckets {
+		if b.tokens+now.Sub(b.last).Seconds()*rate >= burst {
+			delete(l.buckets, key)
+		}
+	}
+}
+
+type principalKey struct{}
+
+func PrincipalFrom(ctx context.Context) (Principal, bool) {
+	principal, ok := ctx.Value(principalKey{}).(Principal)
+	return principal, ok
+}
+
+// Middleware authenticates "Authorization: Bearer px1k_..." with the required
+// scope and rate-limits by key. Responses never say whether a key exists.
+func Middleware(manager Manager, limiter *RateLimiter, required Scope, next http.Handler) http.Handler {
+	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
+		token, ok := strings.CutPrefix(r.Header.Get("Authorization"), "Bearer ")
+		if !ok {
+			w.Header().Set("WWW-Authenticate", `Bearer realm="px1"`)
+			http.Error(w, "API key required", http.StatusUnauthorized)
+			return
+		}
+		principal, err := manager.Authenticate(r.Context(), strings.TrimSpace(token), required)
+		switch {
+		case errors.Is(err, ErrUnauthorized):
+			w.Header().Set("WWW-Authenticate", `Bearer realm="px1", error="invalid_token"`)
+			http.Error(w, "invalid API key", http.StatusUnauthorized)
+			return
+		case errors.Is(err, ErrForbidden):
+			http.Error(w, "API key lacks the "+string(required)+" scope", http.StatusForbidden)
+			return
+		case err != nil:
+			http.Error(w, "API key verification unavailable", http.StatusServiceUnavailable)
+			return
+		}
+		if limiter != nil {
+			if allowed, wait := limiter.Allow(principal.KeyID); !allowed {
+				w.Header().Set("Retry-After", strconv.Itoa(int(math.Ceil(wait.Seconds()))))
+				http.Error(w, "rate limit exceeded", http.StatusTooManyRequests)
+				return
+			}
+		}
+		next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), principalKey{}, principal)))
+	})
+}

diff --git a/internal/hosted/apikeys/keys.go b/internal/hosted/apikeys/keys.go
new file mode 100644
index 0000000..52232a5
--- /dev/null
+++ b/internal/hosted/apikeys/keys.go
@@ -0,0 +1,216 @@
+// Package apikeys issues and verifies per-organization API keys for the
+// public API and the MCP server.
+//
+// A key looks like px1k_<installation>_<key id>_<secret>. The installation and
+// key ID are not secret: they let the server set the tenant before any lookup,
+// so key rows stay behind the same row-level security as every other hosted
+// table. Only a SHA-256 digest of the 256-bit random secret is stored. A fast
+// hash is appropriate here because the secret is random, not a password.
+package apikeys
+
+import (
+	"context"
+	"crypto/rand"
+	"crypto/sha256"
+	"crypto/subtle"
+	"encoding/base64"
+	"encoding/hex"
+	"errors"
+	"fmt"
+	"regexp"
+	"slices"
+	"strconv"
+	"strings"
+	"time"
+)
+
+const (
+	Prefix         = "px1k_"
+	MaxKeyLifetime = 365 * 24 * time.Hour
+	MaxRotation    = 7 * 24 * time.Hour
+	MaxNameBytes   = 100
+)
+
+type Scope string
+
+const (
+	ReviewsRead    Scope = "reviews:read"
+	ReviewsTrigger Scope = "reviews:trigger"
+	FindingsRead   Scope = "findings:read"
+	FindingsWrite  Scope = "findings:write"
+	CodebaseRead   Scope = "codebase:read"
+	RulesRead      Scope = "rules:read"
+	MemoriesRead   Scope = "memories:read"
+)
+
+var knownScopes = map[Scope]bool{ReviewsRead: true, ReviewsTrigger: true, FindingsRead: true, FindingsWrite: true, CodebaseRead: true, RulesRead: true, MemoriesRead: true}
+
+type Key struct {
+	ID             string
+	InstallationID int64
+	Name           string
+	Scopes         []Scope
+	SecretHash     [32]byte
+	CreatedAt      time.Time
+	ExpiresAt      time.Time
+	RevokedAt      time.Time
+	ReplacedBy     string
+}
+
+// Store reads and writes key rows for one tenant. Implementations set
+// px1.installation_id from the installationID argument before querying.
+type Store interface {
+	Insert(ctx context.Context, key Key) error
+	Get(ctx context.Context, installationID int64, id string) (Key, bool, error)
+	// Supersede atomically marks old as replaced by next and moves its expiry
+	// earlier, then inserts next. It fails if old is revoked or already replaced.
+	Supersede(ctx context.Context, installationID int64, oldID string, oldExpiresAt time.Time, next Key) error
+	Revoke(ctx context.Context, installationID int64, id string, at time.Time) error
+}
+
+type Principal struct {
+	InstallationID int64
+	KeyID          string
+	Scopes         []Scope
+}
+
+func (p Principal) Has(scope Scope) bool { return slices.Contains(p.Scopes, scope) }
+
+var (
+	// ErrUnauthorized covers malformed, unknown, wrong, expired, and revoked
+	// keys alike, so callers cannot probe which keys exist.
+	ErrUnauthorized = errors.New("invalid API key")
+	ErrForbidden    = errors.New("API key lacks the required scope")
+)
+
+var tokenPattern = regexp.MustCompile(`^px1k_([1-9][0-9]{0,18})_([0-9a-f]{16})_([A-Za-z0-9_-]{43})$`)
+
+type Manager struct {
+	Store Store
+	Now   func() time.Time
+}
+
+// Issue creates a key and returns its plaintext token exactly once.
+func (m Manager) Issue(ctx context.Context, installationID int64, name string, scopes []Scope, lifetime time.Duration) (string, Key, error) {
+	name = strings.TrimSpace(name)
+	if m.Store == nil || installationID <= 0 || name == "" || len(name) > MaxNameBytes {
+		return "", Key{}, errors.New("store, tenant, and a 1-100 byte name are required")
+	}
+	if lifetime <= 0 || lifetime > MaxKeyLifetime {
+		return "", Key{}, fmt.Errorf("key lifetime must be positive and at most %s", MaxKeyLifetime)
+	}
+	normalized, err := normalizeScopes(scopes)
+	if err != nil {
+		return "", Key{}, err
+	}
+	token, key, err := m.newKey(installationID, name, normalized, lifetime)
+	if err != nil {
+		return "", Key{}, err
+	}
+	if err := m.Store.Insert(ctx, key); err != nil {
+		return "", Key{}, fmt.Errorf("store API key: %w", err)
+	}
+	return token, key, nil
+}
+
+// Rotate issues a replacement with the same name, scopes, and lifetime, and
+// lets the old key keep working for at most overlap so clients can switch.
+func (m Manager) Rotate(ctx context.Context, installationID int64, id string, overlap time.Duration) (string, Key, error) {
+	if m.Store == nil || overlap < 0 || overlap > MaxRotation {
+		return "", Key{}, fmt.Errorf("store and an overlap of at most %s are required", MaxRotation)
+	}
+	old, found, err := m.Store.Get(ctx, installationID, id)
+	if err != nil {
+		return "", Key{}, err
+	}
+	now := m.now()
+	if !found || !old.RevokedAt.IsZero() || old.ReplacedBy != "" || !now.Before(old.ExpiresAt) {
+		return "", Key{}, errors.New("only an active key can be rotated")
+	}
+	token, next, err := m.newKey(installationID, old.Name, old.Scopes, old.ExpiresAt.Sub(old.CreatedAt))
+	if err != nil {
+		return "", Key{}, err
+	}
+	oldExpiry := now.Add(overlap)
+	if old.ExpiresAt.Before(oldExpiry) {
+		oldExpiry = old.ExpiresAt
+	}
+	if err := m.Store.Supersede(ctx, installationID, old.ID, oldExpiry, next); err != nil {
+		return "", Key{}, fmt.Errorf("rotate API key: %w", err)
+	}
+	return token, next, nil
+}
+
+func (m Manager) Revoke(ctx context.Context, installationID int64, id string) error {
+	if m.Store == nil || installationID <= 0 {
+		return errors.New("store and tenant are required")
+	}
+	return m.Store.Revoke(ctx, installationID, id, m.now())
+}
+
+// Authenticate verifies a presented token and, when required is non-empty,
+// that the key holds that scope.
+func (m Manager) Authenticate(ctx context.Context, token string, required Scope) (Principal, error) {
+	match := tokenPattern.FindStringSubmatch(token)
+	if m.Store == nil || match == nil {
+		return Principal{}, ErrUnauthorized
+	}
+	installationID, err := strconv.ParseInt(match[1], 10, 64)
+	if err != nil {
+		return Principal{}, ErrUnauthorized
+	}
+	key, found, err := m.Store.Get(ctx, installationID, match[2])
+	if err != nil {
+		return Principal{}, fmt.Errorf("read API key: %w", err)
+	}
+	digest := sha256.Sum256([]byte(match[3]))
+	if !found || key.InstallationID != installationID || subtle.ConstantTimeCompare(digest[:], key.SecretHash[:]) != 1 {
+		return Principal{}, ErrUnauthorized
+	}
+	if !key.RevokedAt.IsZero() || !m.now().Before(key.ExpiresAt) {
+		return Principal{}, ErrUnauthorized
+	}
+	principal := Principal{InstallationID: key.InstallationID, KeyID: key.ID, Scopes: append([]Scope{}, key.Scopes...)}
+	if required != "" && !principal.Has(required) {
+		return principal, ErrForbidden
+	}
+	return principal, nil
+}
+
+func (m Manager) newKey(installationID int64, name string, scopes []Scope, lifetime time.Duration) (string, Key, error) {
+	idBytes, secretBytes := make([]byte, 8), make([]byte, 32)
+	if _, err := rand.Read(idBytes); err != nil {
+		return "", Key{}, err
+	}
+	if _, err := rand.Read(secretBytes); err != nil {
+		return "", Key{}, err
+	}
+	id, secret := hex.EncodeToString(idBytes), base64.RawURLEncoding.EncodeToString(secretBytes)
+	now := m.now()
+	key := Key{ID: id, InstallationID: installationID, Name: name, Scopes: scopes, SecretHash: sha256.Sum256([]byte(secret)), CreatedAt: now, ExpiresAt: now.Add(lifetime)}
+	return fmt.Sprintf("%s%d_%s_%s", Prefix, installationID, id, secret), key, nil
+}
+
+func (m Manager) now() time.Time {
+	if m.Now != nil {
+		return m.Now().UTC()
+	}
+	return time.Now().UTC()
+}
+
+func normalizeScopes(scopes []Scope) ([]Scope, error) {
+	if len(scopes) == 0 {
+		return nil, errors.New("at least one scope is required")
+	}
+	normalized := []Scope{}
+	for _, scope := range scopes {
+		if !knownScopes[scope] {
+			return nil, fmt.Errorf("unknown scope %q", scope)
+		}
+		if !slices.Contains(normalized, scope) {
+			normalized = append(normalized, scope)
+		}
+	}
+	slices.Sort(normalized)
+	return normalized, nil
+}

diff --git a/internal/hosted/apikeys/keys_test.go b/internal/hosted/apikeys/keys_test.go
new file mode 100644
index 0000000..3c4034d
--- /dev/null
+++ b/internal/hosted/apikeys/keys_test.go
@@ -0,0 +1,229 @@
+package apikeys
+
+import (
+	"context"
+	"errors"
+	"net/http"
+	"net/http/httptest"
+	"strings"
+	"sync"
+	"testing"
+	"time"
+)
+
+type memoryStore struct {
+	mu   sync.Mutex
+	keys map[int64]map[string]Key
+}
+
+func (s *memoryStore) tenant(id int64) map[string]Key {
+	if s.keys == nil {
+		s.keys = map[int64]map[string]Key{}
+	}
+	if s.keys[id] == nil {
+		s.keys[id] = map[string]Key{}
+	}
+	return s.keys[id]
+}
+
+func (s *memoryStore) Insert(_ context.Context, key Key) error {
+	s.mu.Lock()
+	defer s.mu.Unlock()
+	s.tenant(key.InstallationID)[key.ID] = key
+	return nil
+}
+
+func (s *memoryStore) Get(_ context.Context, installationID int64, id string) (Key, bool, error) {
+	s.mu.Lock()
+	defer s.mu.Unlock()
+	key, ok := s.tenant(installationID)[id]
+	return key, ok, nil
+}
+
+func (s *memoryStore) Supersede(_ context.Context, installationID int64, oldID string, oldExpiresAt time.Time, next Key) error {
+	s.mu.Lock()
+	defer s.mu.Unlock()
+	old, ok := s.tenant(installationID)[oldID]
+	if !ok || !old.RevokedAt.IsZero() || old.ReplacedBy != "" {
+		return errors.New("not active")
+	}
+	old.ReplacedBy, old.ExpiresAt = next.ID, oldExpiresAt
+	s.tenant(installationID)[oldID] = old
+	s.tenant(installationID)[next.ID] = next
+	return nil
+}
+
+func (s *memoryStore) Revoke(_ context.Context, installationID int64, id string, at time.Time) error {
+	s.mu.Lock()
+	defer s.mu.Unlock()
+	key := s.tenant(installationID)[id]
+	key.RevokedAt = at
+	s.tenant(installationID)[id] = key
+	return nil
+}
+
+type clock struct{ now time.Time }
+
+func (c *clock) Now() time.Time { return c.now }
+
+func newManager() (Manager, *memoryStore, *clock) {
+	store, c := &memoryStore{}, &clock{now: time.Date(2026, 11, 7, 0, 0, 0, 0, time.UTC)}
+	return Manager{Store: store, Now: c.Now}, store, c
+}
+
+func TestIssuedKeysStoreOnlyADigestAndAuthenticateWithScopes(t *testing.T) {
+	manager, store, _ := newManager()
+	token, key, err := manager.Issue(context.Background(), 42, "ci bot", []Scope{FindingsRead, ReviewsRead, FindingsRead}, 30*24*time.Hour)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if !strings.HasPrefix(token, "px1k_42_"+key.ID+"_") || len(key.Scopes) != 2 {
+		t.Fatalf("token=%q scopes=%v", token, key.Scopes)
+	}
+	secret := token[strings.LastIndex(token, "_")+1:]
+	stored, _, _ := store.Get(context.Background(), 42, key.ID)
+	if strings.Contains(stored.Name+string(stored.SecretHash[:]), secret) {
+		t.Fatal("plaintext secret stored")
+	}
+	principal, err := manager.Authenticate(context.Background(), token, FindingsRead)
+	if err != nil || principal.InstallationID != 42 || principal.KeyID != key.ID {
+		t.Fatalf("principal=%#v err=%v", principal, err)
+	}
+	if _, err := manager.Authenticate(context.Background(), token, ReviewsTrigger); !errors.Is(err, ErrForbidden) {
+		t.Fatalf("missing scope: %v", err)
+	}
+}
+
+func TestAuthenticationFailuresAreIndistinguishable(t *testing.T) {
+	manager, _, c := newManager()
+	token, key, _ := manager.Issue(context.Background(), 42, "k", []Scope{ReviewsRead}, time.Hour)
+	wrongSecret := token[:len(token)-1] + map[bool]string{true: "A", false: "B"}[token[len(token)-1] != 'A']
+	otherTenant := strings.Replace(token, "px1k_42_", "px1k_43_", 1)
+	for name, presented := range map[string]string{
+		"empty": "", "garbage": "Bearer nope", "wrong secret": wrongSecret, "other tenant": otherTenant,
+		"unknown id": strings.Replace(token, key.ID, "0123456789abcdef", 1), "leading zero tenant": strings.Replace(token, "px1k_42", "px1k_042", 1),
+	} {
+		if _, err := manager.Authenticate(context.Background(), presented, ""); !errors.Is(err, ErrUnauthorized) {
+			t.Fatalf("%s: %v", name, err)
+		}
+	}
+	c.now = c.now.Add(time.Hour)
+	if _, err := manager.Authenticate(context.Background(), token, ""); !errors.Is(err, ErrUnauthorized) {
+		t.Fatal("expired key accepted")
+	}
+}
+
+func TestRotationOverlapsThenRetiresTheOldKey(t *testing.T) {
+	manager, _, c := newManager()
+	oldToken, old, _ := manager.Issue(context.Background(), 42, "deploy", []Scope{ReviewsRead}, 90*24*time.Hour)
+	newToken, next, err := manager.Rotate(context.Background(), 42, old.ID, time.Hour)
+	if err != nil || next.Name != "deploy" || next.Scopes[0] != ReviewsRead || next.ID == old.ID {
+		t.Fatalf("next=%#v err=%v", next, err)
+	}
+	for _, token := range []string{oldToken, newToken} {
+		if _, err := manager.Authenticate(context.Background(), token, ""); err != nil {
+			t.Fatalf("key unusable during overlap: %v", err)
+		}
+	}
+	if _, _, err := manager.Rotate(context.Background(), 42, old.ID, time.Hour); err == nil {
+		t.Fatal("a superseded key was rotated twice")
+	}
+	c.now = c.now.Add(time.Hour)
+	if _, err := manager.Authenticate(context.Background(), oldToken, ""); !errors.Is(err, ErrUnauthorized) {
+		t.Fatal("old key outlived its overlap")
+	}
+	if _, err := manager.Authenticate(context.Background(), newToken, ""); err != nil {
+		t.Fatal(err)
+	}
+	if _, _, err := manager.Rotate(context.Background(), 42, next.ID, 8*24*time.Hour); err == nil {
+		t.Fatal("overlap above seven days accepted")
+	}
+	if err := manager.Revoke(context.Background(), 42, next.ID); err != nil {
+		t.Fatal(err)
+	}
+	if _, err := manager.Authenticate(context.Background(), newToken, ""); !errors.Is(err, ErrUnauthorized) {
+		t.Fatal("revoked key accepted")
+	}
+}
+
+func TestIssueValidatesInput(t *testing.T) {
+	manager, _, _ := newManager()
+	for name, issue := range map[string]func() error{
+		"no scopes": func() error { _, _, err := manager.Issue(context.Background(), 1, "k", nil, time.Hour); return err },
+		"unknown scope": func() error {
+			_, _, err := manager.Issue(context.Background(), 1, "k", []Scope{"admin"}, time.Hour)
+			return err
+		},
+		"forever": func() error {
+			_, _, err := manager.Issue(context.Background(), 1, "k", []Scope{ReviewsRead}, 400*24*time.Hour)
+			return err
+		},
+		"no tenant": func() error {
+			_, _, err := manager.Issue(context.Background(), 0, "k", []Scope{ReviewsRead}, time.Hour)
+			return err
+		},
+		"no name": func() error {
+			_, _, err := manager.Issue(context.Background(), 1, " ", []Scope{ReviewsRead}, time.Hour)
+			return err
+		},
+	} {
+		if issue() == nil {
+			t.Fatalf("%s accepted", name)
+		}
+	}
+}
+
+func TestRateLimiterRefillsPerKey(t *testing.T) {
+	now := time.Date(2026, 11, 7, 0, 0, 0, 0, time.UTC)
+	limiter := &RateLimiter{PerMinute: 60, Burst: 2, Now: func() time.Time { return now }}
+	if ok, _ := limiter.Allow("a"); !ok {
+		t.Fatal("first request refused")
+	}
+	limiter.Allow("a")
+	ok, wait := limiter.Allow("a")
+	if ok || wait != time.Second {
+		t.Fatalf("burst exceeded: ok=%v wait=%s", ok, wait)
+	}
+	if ok, _ := limiter.Allow("b"); !ok {
+		t.Fatal("keys share a bucket")
+	}
+	now = now.Add(time.Second)
+	if ok, _ := limiter.Allow("a"); !ok {
+		t.Fatal("bucket did not refill")
+	}
+}
+
+func TestMiddlewareMapsFailuresToHTTPStatus(t *testing.T) {
+	manager, _, _ := newManager()
+	token, _, _ := manager.Issue(context.Background(), 42, "k", []Scope{FindingsRead}, time.Hour)
+	limiter := &RateLimiter{PerMinute: 1, Burst: 1}
+	handler := Middleware(manager, limiter, FindingsRead, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
+		principal, _ := PrincipalFrom(r.Context())
+		w.Write([]byte(principal.KeyID))
+	}))
+	forbidden := Middleware(manager, nil, ReviewsTrigger, handler)
+	request := func(h http.Handler, auth string) *httptest.ResponseRecorder {
+		r := httptest.NewRequest(http.MethodGet, "/", nil)
+		if auth != "" {
+			r.Header.Set("Authorization", auth)
+		}
+		w := httptest.NewRecorder()
+		h.ServeHTTP(w, r)
+		return w
+	}
+	if w := request(handler, ""); w.Code != http.StatusUnauthorized || w.Header().Get("WWW-Authenticate") == "" {
+		t.Fatalf("missing key: %d", w.Code)
+	}
